import React, { useCallback, useEffect, useMemo, useState } from "react";

const API_URL = (
  process.env.REACT_APP_API_URL || "http://localhost:5000"
).replace(/\/$/, "");

const AdminPanel = () => {
  const [bookings, setBookings] = useState([]);
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState("");
  const [error, setError] = useState("");

  // ==========================================
  // Logout
  // ==========================================

  const logout = useCallback(() => {
    localStorage.removeItem("adminToken");
    window.location.href = "/admin/login";
  }, []);

  // ==========================================
  // API Request
  // ==========================================

  const apiRequest = useCallback(
    async (endpoint, options = {}) => {
      const token = localStorage.getItem("adminToken");

      if (!token) {
        logout();
        throw new Error("Authentication required");
      }

      const response = await fetch(`${API_URL}${endpoint}`, {
        ...options,
        headers: {
          ...(options.body
            ? { "Content-Type": "application/json" }
            : {}),
          ...(options.headers || {}),
          Authorization: `Bearer ${token}`,
        },
      });

      let data = {};

      try {
        data = await response.json();
      } catch {
        data = {};
      }

      console.log("API:", endpoint);
      console.log("Status:", response.status);
      console.log("Response:", data);

      if (response.status === 401 || response.status === 403) {
        localStorage.removeItem("adminToken");
        logout();
        throw new Error("Session expired. Please login again.");
      }

      if (!response.ok) {
        throw new Error(
          data.error || "Something went wrong with the server."
        );
      }

      return data;
    },
    [logout]
  );

  // ==========================================
  // Fetch Bookings
  // ==========================================

  const fetchBookings = useCallback(async () => {
  setLoading(true);
  setError("");

  try {
    const data = await apiRequest("/api/admin/bookings");

    console.log("BOOKINGS RESPONSE:", data);

    if (data.success && Array.isArray(data.bookings)) {
      console.log("BOOKINGS FOUND:", data.bookings);
      console.log("BOOKING COUNT:", data.bookings.length);

      setBookings(data.bookings);
    } else {
      console.error("Invalid booking response:", data);
      setBookings([]);
      setError("Invalid booking data received from server.");
    }
  } catch (error) {
    console.error("Fetch bookings error:", error);
    setBookings([]);
    setError(error.message || "Failed to fetch bookings.");
  } finally {
    setLoading(false);
  }
}, [apiRequest]);

  // ==========================================
  // Initial Load
  // ==========================================

  useEffect(() => {
    const token = localStorage.getItem("adminToken");

    if (!token) {
      setLoading(false);
      return;
    }

    fetchBookings();
  }, [fetchBookings]);

  // ==========================================
  // Mark Completed
  // ==========================================

  const markCompleted = async (id) => {
    if (!id) return;

    const confirmed = window.confirm(
      "Mark this booking as completed?"
    );

    if (!confirmed) return;

    setActionLoading(`complete-${id}`);
    setError("");

    try {
      await apiRequest(`/api/bookings/${id}/complete`, {
        method: "PUT",
      });

      await fetchBookings();
    } catch (err) {
      console.error("COMPLETE ERROR:", err);
      setError(err.message || "Failed to complete booking.");
    } finally {
      setActionLoading("");
    }
  };

  // ==========================================
  // Delete Booking
  // ==========================================

  const deleteBooking = async (id) => {
    if (!id) return;

    const confirmed = window.confirm(
      "Are you sure you want to permanently delete this booking?"
    );

    if (!confirmed) return;

    setActionLoading(`delete-${id}`);
    setError("");

    try {
      await apiRequest(`/api/bookings/${id}`, {
        method: "DELETE",
      });

      await fetchBookings();
    } catch (err) {
      console.error("DELETE ERROR:", err);
      setError(err.message || "Failed to delete booking.");
    } finally {
      setActionLoading("");
    }
  };

  // ==========================================
  // Export CSV
  // ==========================================

  const exportCSV = async () => {
    const token = localStorage.getItem("adminToken");

    if (!token) {
      logout();
      return;
    }

    setActionLoading("export");
    setError("");

    try {
      const response = await fetch(
        `${API_URL}/api/bookings/export`,
        {
          method: "GET",
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      if (response.status === 401 || response.status === 403) {
        localStorage.removeItem("adminToken");
        logout();
        return;
      }

      if (!response.ok) {
        throw new Error("Failed to export bookings.");
      }

      const blob = await response.blob();

      const downloadUrl = window.URL.createObjectURL(blob);

      const link = document.createElement("a");

      link.href = downloadUrl;
      link.download = "pest-control-bookings.csv";

      document.body.appendChild(link);

      link.click();

      link.remove();

      window.URL.revokeObjectURL(downloadUrl);
    } catch (err) {
      console.error("EXPORT ERROR:", err);
      setError(err.message || "Failed to export bookings.");
    } finally {
      setActionLoading("");
    }
  };

  // ==========================================
  // Statistics
  // ==========================================

  const statistics = useMemo(() => {
    const total = bookings.length;

    const completed = bookings.filter(
      (booking) => booking.completed === true
    ).length;

    const pending = total - completed;

    return {
      total,
      completed,
      pending,
    };
  }, [bookings]);

  // ==========================================
  // Format Date
  // ==========================================

  const formatDate = (date) => {
    if (!date) return "N/A";

    const parsedDate = new Date(date);

    if (Number.isNaN(parsedDate.getTime())) {
      return "Invalid date";
    }

    return parsedDate.toLocaleDateString("en-IN", {
      day: "2-digit",
      month: "short",
      year: "numeric",
    });
  };

  // ==========================================
  // Format Created Date
  // ==========================================

  const formatCreatedAt = (date) => {
    if (!date) return "N/A";

    const parsedDate = new Date(date);

    if (Number.isNaN(parsedDate.getTime())) {
      return "N/A";
    }

    return parsedDate.toLocaleString("en-IN", {
      day: "2-digit",
      month: "short",
      year: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    });
  };

  // ==========================================
  // Login Required
  // ==========================================

  const token = localStorage.getItem("adminToken");

  if (!token) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50 px-4">
        <div className="bg-white rounded-xl shadow-md p-8 text-center max-w-md w-full">

          <div className="text-5xl mb-4">
            🔐
          </div>

          <h1 className="text-2xl font-bold text-gray-900 mb-2">
            Admin Login Required
          </h1>

          <p className="text-gray-600 mb-6">
            Please login as an administrator to access the dashboard.
          </p>

          <a
            href="/admin/login"
            className="inline-block bg-primary text-white px-6 py-3 rounded-lg font-medium hover:opacity-90"
          >
            Go to Admin Login
          </a>

        </div>
      </div>
    );
  }

  // ==========================================
  // Dashboard
  // ==========================================

  return (
    <div className="min-h-screen bg-gray-50 px-4 py-8">

      <div className="max-w-7xl mx-auto">

        {/* HEADER */}

        <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4 mb-8">

          <div>
            <p className="text-sm text-gray-500">
              Pest Control Management
            </p>

            <h1 className="text-3xl font-bold text-gray-900">
              Admin Dashboard
            </h1>
          </div>

          <div className="flex flex-wrap gap-2">

            <button
              onClick={fetchBookings}
              disabled={loading}
              className="px-4 py-2 rounded-lg border border-gray-300 bg-white text-gray-700 font-medium hover:bg-gray-100 disabled:opacity-50"
            >
              {loading ? "Refreshing..." : "↻ Refresh"}
            </button>

            <button
              onClick={exportCSV}
              disabled={
                actionLoading === "export" ||
                bookings.length === 0
              }
              className="px-4 py-2 rounded-lg bg-primary text-white font-medium hover:opacity-90 disabled:opacity-50"
            >
              {actionLoading === "export"
                ? "Exporting..."
                : "Export CSV"}
            </button>

            <button
              onClick={logout}
              className="px-4 py-2 rounded-lg bg-gray-800 text-white font-medium hover:bg-gray-900"
            >
              Logout
            </button>

          </div>
        </div>

        {/* ERROR */}

        {error && (
          <div className="mb-6 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-red-700">

            <div className="flex justify-between gap-4">

              <p>
                {error}
              </p>

              <button
                onClick={() => setError("")}
                className="font-bold"
              >
                ×
              </button>

            </div>
          </div>
        )}

        {/* STATISTICS */}

        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-8">

          <div className="bg-white rounded-xl shadow-sm border p-5">

            <p className="text-sm text-gray-500">
              Total Bookings
            </p>

            <p className="text-3xl font-bold text-gray-900 mt-2">
              {statistics.total}
            </p>

          </div>

          <div className="bg-white rounded-xl shadow-sm border p-5">

            <p className="text-sm text-gray-500">
              Pending
            </p>

            <p className="text-3xl font-bold text-yellow-600 mt-2">
              {statistics.pending}
            </p>

          </div>

          <div className="bg-white rounded-xl shadow-sm border p-5">

            <p className="text-sm text-gray-500">
              Completed
            </p>

            <p className="text-3xl font-bold text-green-600 mt-2">
              {statistics.completed}
            </p>

          </div>

        </div>

        {/* LOADING */}

        {loading && (
          <div className="bg-white rounded-xl shadow-sm p-12 text-center">

            <div className="animate-spin w-10 h-10 border-4 border-gray-200 border-t-primary rounded-full mx-auto mb-4" />

            <p className="text-gray-600">
              Loading bookings...
            </p>

          </div>
        )}

        {/* NO BOOKINGS */}

        {!loading && bookings.length === 0 && (
          <div className="bg-white rounded-xl shadow-sm p-12 text-center">

            <div className="text-5xl mb-4">
              📋
            </div>

            <h2 className="text-xl font-semibold text-gray-900 mb-2">
              No bookings found
            </h2>

            <p className="text-gray-500 mb-5">
              The API is reachable, but there are no bookings in the response.
            </p>

            <button
              onClick={fetchBookings}
              className="px-5 py-2 rounded-lg bg-primary text-white"
            >
              Refresh Bookings
            </button>

          </div>
        )}

        {/* BOOKINGS */}

        {!loading && bookings.length > 0 && (
          <div className="bg-white rounded-xl shadow-sm overflow-hidden">

            <div className="px-6 py-5 border-b">

              <h2 className="text-xl font-bold text-gray-900">
                Customer Bookings
              </h2>

              <p className="text-sm text-gray-500 mt-1">
                {bookings.length} booking
                {bookings.length !== 1 ? "s" : ""} found
              </p>

            </div>

            <div className="overflow-x-auto">

              <table className="w-full">

                <thead>

                  <tr className="bg-gray-100 text-left text-sm text-gray-600">

                    <th className="px-4 py-4">
                      Customer
                    </th>

                    <th className="px-4 py-4">
                      Mobile
                    </th>

                    <th className="px-4 py-4">
                      Address
                    </th>

                    <th className="px-4 py-4">
                      Service
                    </th>

                    <th className="px-4 py-4">
                      Date
                    </th>

                    <th className="px-4 py-4">
                      Time
                    </th>

                    <th className="px-4 py-4">
                      Status
                    </th>

                    <th className="px-4 py-4">
                      Actions
                    </th>

                  </tr>

                </thead>

                <tbody className="divide-y divide-gray-100">

                  {bookings.map((booking) => {

                    const id = booking._id;

                    const completing =
                      actionLoading === `complete-${id}`;

                    const deleting =
                      actionLoading === `delete-${id}`;

                    return (
                      <tr
                        key={id}
                        className={
                          booking.completed
                            ? "bg-green-50"
                            : "hover:bg-gray-50"
                        }
                      >

                        <td className="px-4 py-4">

                          <p className="font-semibold text-gray-900">
                            {booking.fullName || "N/A"}
                          </p>

                        </td>

                        <td className="px-4 py-4">

                          <a
                            href={`tel:${booking.mobile}`}
                            className="text-primary font-medium"
                          >
                            {booking.mobile || "N/A"}
                          </a>

                        </td>

                        <td className="px-4 py-4">

                          <p className="text-gray-700 max-w-xs">
                            {booking.address || "N/A"}
                          </p>

                        </td>

                        <td className="px-4 py-4">

                          <span className="inline-flex px-3 py-1 rounded-full bg-blue-50 text-blue-700 text-xs font-medium">

                            {booking.service || "N/A"}

                          </span>

                        </td>

                        <td className="px-4 py-4">

                          <p className="font-medium">
                            {formatDate(booking.preferredDate)}
                          </p>

                        </td>

                        <td className="px-4 py-4">

                          <p className="text-gray-700">
                            {booking.preferredTime || "N/A"}
                          </p>

                        </td>

                        <td className="px-4 py-4">

                          {booking.completed ? (

                            <span className="inline-flex px-3 py-1 rounded-full bg-green-100 text-green-700 text-xs font-semibold">
                              Completed
                            </span>

                          ) : (

                            <span className="inline-flex px-3 py-1 rounded-full bg-yellow-100 text-yellow-700 text-xs font-semibold">
                              Pending
                            </span>

                          )}

                        </td>

                        <td className="px-4 py-4">

                          <div className="flex gap-2">

                            {!booking.completed && (
                              <button
                                onClick={() =>
                                  markCompleted(id)
                                }
                                disabled={
                                  completing ||
                                  deleting
                                }
                                className="px-3 py-2 rounded-lg bg-green-600 text-white text-xs font-medium hover:bg-green-700 disabled:opacity-50"
                              >
                                {completing
                                  ? "Updating..."
                                  : "Complete"}
                              </button>
                            )}

                            <button
                              onClick={() =>
                                deleteBooking(id)
                              }
                              disabled={
                                completing ||
                                deleting
                              }
                              className="px-3 py-2 rounded-lg bg-red-600 text-white text-xs font-medium hover:bg-red-700 disabled:opacity-50"
                            >
                              {deleting
                                ? "Deleting..."
                                : "Delete"}
                            </button>

                          </div>

                        </td>

                      </tr>
                    );
                  })}

                </tbody>

              </table>

            </div>

          </div>
        )}

      </div>

    </div>
  );
};

export default AdminPanel;
